import json, statistics, collections
from pathlib import Path
r = json.loads(Path("data/experiments/jspace_compact_performance/20261113_v1/profile/result.json").read_text())
results = []
for arm, rows in r.items():
    for mode in ("prefill", "decode"):
        selected = [x for x in rows if x["mode"] == mode]
        geometry = 0.; down = collections.defaultdict(float); copies = [0., 0.]
        kernels = []; memory = []
        for x in selected:
            divisor = x["iterations"] * len(selected)
            kernels.append(sum(v for k, v in x["kernels"].items() if not k.startswith(("Memset", "Memcpy"))) / x["iterations"])
            memory.append(sum(v for k, v in x["kernels"].items() if k.startswith(("Memset", "Memcpy"))) / x["iterations"])
            for o in x["top_operators"]:
                if o["name"] == "aten::copy_":
                    copies[0] += o["self_device_us"] / divisor
                    copies[1] += o["count"] / divisor
                if o["name"] not in ("aten::mm", "aten::bmm"):
                    continue
                shapes = o["input_shapes"]
                if len(shapes) < 2:
                    continue
                if shapes[1][-2:] in ([2048, 1536], [1536, 2048]):
                    geometry += o["self_device_us"] / divisor
                if len(shapes[0]) == 2 and shapes[0][1] in (11008, 10309) and shapes[1][-1] == 1536:
                    down[str(shapes[0][1])] += o["self_device_us"] / divisor
        results.append(dict(arm=arm, mode=mode, lengths=[x["tokens"] for x in selected], actual_kernels_per_call=statistics.mean(kernels), memory_activities_per_call=statistics.mean(memory), geometry_device_us_per_call=geometry, down_projection_device_us_per_call=dict(down), copy_device_us_per_call=copies[0], copy_calls=copies[1]))
